import sys
from collections import deque, defaultdict

def main():
    import sys
    input = sys.stdin.read().split('\n')

    index = 0
    results = []
    while index < len(input):
        t = int(input[index])
        index += 1

        for _ in range(t):
            n, m = map(int, input[index].split())
            index += 1

            graph = defaultdict(list)
            for _ in range(m):
                a, b = map(int, input[index].split())
                graph[a].append(b)
                index += 1

            visited = [False] * (n + 1)
            paths_count = [0] * (n + 1)
            in_stack = [False] * (n + 1)
            stack = deque()

            def dfs(node):
                if in_stack[node]:
                    return True
                if visited[node]:
                    return False

                visited[node] = True
                in_stack[node] = True
                stack.append(node)

                for neighbor in graph[node]:
                    if dfs(neighbor):
                        return True

                in_stack[node] = False
                stack.pop()
                return False

            def count_paths(node):
                if paths_count[node] != 0:
                    return paths_count[node]

                if node == 1:
                    paths_count[node] = 1
                    return 1

                count = 0
                for neighbor in graph[node]:
                    if paths_count[neighbor] == -1:
                        count = -1
                        break
                    elif paths_count[neighbor] != 0:
                        count += paths_count[neighbor]
                        if count > 1:
                            count = -1
                            break

                paths_count[node] = count
                return count

            cycle_detected = dfs(1)

            if cycle_detected:
                while stack:
                    node = stack.popleft()
                    paths_count[node] = -1

            for i in range(1, n + 1):
                if paths_count[i] == 0:
                    count_paths(i)

            result = []
            for i in range(1, n + 1):
                if not visited[i]:
                    result.append(0)
                else:
                    result.append(paths_count[i])

            results.append(' '.join(map(str, result)))

    print('\n'.join(results))

if __name__ == "__main__":
    main()
